llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Ipratropium, the closest analogue (quaternary ammonium tropane ester, N-isopropyl vs N-ethyl), had an absolute oral bioavailability of 3.3% (range 0.9–6.1%) in ten healthy male volunteers after a 20 mg oral dose versus i.v.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tiotropium, a quaternary ammonium tropane with the same epoxide bridge as the query, had an absolute oral bioavailability of only 2–3% in healthy humans, demonstrating that the epoxide-containing quaternary tropane class is poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "One ipratropium study reported about 32% oral absorption at a 30 mg dose by AUC comparison, which conflicts with the majority of low-bioavailability values and introduces uncertainty about dose-dependence or methodology.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tropisetron, a non-quaternary tropane ester, had an absolute oral bioavailability of 58% (range 17–140%) in healthy subjects, showing that the tropane ester scaffold can be absorbed when the nitrogen is not permanently charged.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester (oxitropium-like). The closest analogue ipratropium has absolute oral F of 2–3.3% in multiple human studies, and tiotropium, which shares the epoxide bridge, has F of 2–3%. These direct human data strongly support F <20%. A single ipratropium outlier (~32% at 30 mg) and the high-F tertiary-amine tropisetron are outweighed by the consistent quaternary-ammonium low-bioavailability phenotype.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule; prediction relies on close analogues.",
    "One ipratropium record reports ~32% at 30 mg, conflicting with multiple 2–3.3% values; dose-dependence or methodological differences are unresolved.",
    "Tropisetron shows that non-quaternary tropane esters can be well absorbed, so the permanent positive charge is the presumed dominant liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

